import{_ as o,o as s,c as a,a as e}from"./chunks/framework.DzJZdBQK.js";const m=JSON.parse('{"title":"写作课作业-037","description":"","frontmatter":{"date":"2020-08-25T21:45:22","title":"写作课作业-037","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/037.md","filePath":"posts/homework/037.md"}'),l={name:"posts/homework/037.md"};function n(r,t,p,i,c,u){return s(),a("div",null,[...t[0]||(t[0]=[e("blockquote",null,[e("p",null,"8.25.写作作业：描述自己一到两次做事“懈怠”的经历，你或遇到的牛人是怎么解决“懈怠”的？用一个递进和类比。")],-1),e("p",null,"说说自己最近一次懈怠乃至说半途而废的例子。践行群招募“打卡立志”的开发志愿者，看了项目需求不难。自己就想自己Go语言也懂，能接触区块链开发，还能补补前端开发，多好啊，于是自己就搞起来了。刚开始天天晚上弄，算是把后端的基础框架搞起了。看到其他志愿者的群里进度，自己也是暗暗使劲。但真到开发前端时就出现懈怠的情况了，前端环境好不容易起来，但Tyepscipt和Vuetify不是太熟，基本都要靠查文档，进度明显就慢下来，也不能天天晚上写代码了。后面看群里进度挺快，心里想的是都已经开发完了，后面还有查Mixin开发文档，自己还折腾啥。接下来好几天没更新，然后就没了然后。今天写下来才发现当时的初心和放弃的原因那真是大相径庭。",-1),e("p",null,"问过前领导，你是开发出生后面怎么销售呢？他说白天经常吃闭门羹，晚上回来敲代码补元气。后来次数多了也就习惯了，然后产品卖出去，效果还不错，信心就起来了。",-1),e("p",null,"问过之前合伙人，像我们这样非医学专业的，怎么能做到天天啃医疗专业书籍呢？他说啃不动的时候就自己做心理建设，一天也有要建设个几次吧。",-1),e("p",null,"开始做一件新的事情的时候，会有一段兴奋期，就像打了鸡血似的。然而这时容易低估一件事情的难度和高估自己的能力。兴奋劲一过，当问题出现的时候，当速度变慢的时候，当挑战增多的时候，就容易出现懈怠，总想退回自己的舒适圈，其实是自己没认清做这件事情的意义，没有做好心理建设。为自己正在做的事情赋予重大的意义，常做心理建设——在自己亢奋时拉回正轨，在自己低落时重拾信心，在自己迷茫时指引方向。",-1)])])}const _=o(l,[["render",n]]);export{m as __pageData,_ as default};
